/*
 * Live filter for the settings reference (settings.md, generated by
 * mkdocs/settings_page.py).
 *
 * Every key is one table row; a query hides the rows whose text does not
 * contain it, opens the "Advanced" fold of a section when a match is inside it,
 * and hides a section with no match at all. The row text includes the key, its
 * C path, type, default, allowed values and summary, so "length", "ghost" or
 * "dispersed" find what a reader is actually looking for, not only key names.
 *
 * Material swaps the page body on navigation without a reload, so the binding
 * is made through `document$`, the observable it exposes for that; on every
 * other page the input does not exist and nothing happens. `?filter=...` in the
 * URL pre-fills the query, so a filtered view can be linked to. (Not `?q=`:
 * Material's own search reads that one and would open its overlay.)
 */
document$.subscribe(() => {
  const input = document.getElementById("mftl-settings-filter");
  if (!input) return;

  const sections = Array.from(document.querySelectorAll(".mftl-settings-section"));
  const counter = document.querySelector(".mftl-settings-filter-count");
  const empty = document.querySelector(".mftl-settings-empty");
  const rows = sections.flatMap((s) => Array.from(s.querySelectorAll("tbody tr")));
  const total = rows.length;

  const apply = () => {
    const terms = input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
    let shown = 0;

    for (const row of rows) {
      const text = row.textContent.toLowerCase();
      const hit = terms.every((t) => text.includes(t));
      row.hidden = !hit;
      if (hit) shown += 1;
    }

    for (const section of sections) {
      const visible = section.querySelectorAll("tbody tr:not([hidden])").length;
      section.hidden = terms.length > 0 && visible === 0;
      for (const fold of section.querySelectorAll("details")) {
        const inside = fold.querySelectorAll("tbody tr:not([hidden])").length;
        fold.hidden = terms.length > 0 && inside === 0;
        if (terms.length > 0) fold.open = inside > 0;
      }
    }

    if (counter) counter.textContent = terms.length ? `${shown} of ${total} keys` : `${total} keys`;
    if (empty) empty.hidden = !(terms.length > 0 && shown === 0);
  };

  /* A filtered view is shareable: settings/?filter=ghost opens with the query in place. */
  const initial = new URLSearchParams(window.location.search).get("filter");
  if (initial && !input.value) input.value = initial;

  input.addEventListener("input", apply);
  apply();
});
